window.KH_SURA(60, {"sura": "الممتحنة", "n": 60, "ayat": {"1": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ تُلْقُونَ إِلَيْهِمْ بِالْمَوَدَّةِ وَقَدْ كَفَرُوا بِمَا جَاءَكُمْ مِنَ الْحَقِّ يُخْرِجُونَ الرَّسُولَ وَإِيَّاكُمْ أَنْ تُؤْمِنُوا بِاللَّهِ رَبِّكُمْ إِنْ كُنْتُمْ خَرَجْتُمْ جِهَادًا فِي سَبِيلِي وَابْتِغَاءَ مَرْضَاتِي تُسِرُّونَ إِلَيْهِمْ بِالْمَوَدَّةِ وَأَنَا أَعْلَمُ بِمَا أَخْفَيْتُمْ وَمَا أَعْلَنْتُمْ وَمَنْ يَفْعَلْهُ مِنْكُمْ فَقَدْ ضَلَّ سَوَاءَ السَّبِيلِ", "2": "إِنْ يَثْقَفُوكُمْ يَكُونُوا لَكُمْ أَعْدَاءً وَيَبْسُطُوا إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُمْ بِالسُّوءِ وَوَدُّوا لَوْ تَكْفُرُونَ", "3": "لَنْ تَنْفَعَكُمْ أَرْحَامُكُمْ وَلَا أَوْلَادُكُمْ يَوْمَ الْقِيَامَةِ يَفْصِلُ بَيْنَكُمْ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", "4": "قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ وَالَّذِينَ مَعَهُ إِذْ قَالُوا لِقَوْمِهِمْ إِنَّا بُرَآءُ مِنْكُمْ وَمِمَّا تَعْبُدُونَ مِنْ دُونِ اللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ الْعَدَاوَةُ وَالْبَغْضَاءُ أَبَدًا حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ إِلَّا قَوْلَ إِبْرَاهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَا أَمْلِكُ لَكَ مِنَ اللَّهِ مِنْ شَيْءٍ رَبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ", "5": "رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ", "6": "لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَمَنْ يَتَوَلَّ فَإِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ", "7": "عَسَى اللَّهُ أَنْ يَجْعَلَ بَيْنَكُمْ وَبَيْنَ الَّذِينَ عَادَيْتُمْ مِنْهُمْ مَوَدَّةً وَاللَّهُ قَدِيرٌ وَاللَّهُ غَفُورٌ رَحِيمٌ", "8": "لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ وَلَمْ يُخْرِجُوكُمْ مِنْ دِيَارِكُمْ أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ إِنَّ اللَّهَ يُحِبُّ الْمُقْسِطِينَ", "9": "إِنَّمَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ قَاتَلُوكُمْ فِي الدِّينِ وَأَخْرَجُوكُمْ مِنْ دِيَارِكُمْ وَظَاهَرُوا عَلَى إِخْرَاجِكُمْ أَنْ تَوَلَّوْهُمْ وَمَنْ يَتَوَلَّهُمْ فَأُولَئِكَ هُمُ الظَّالِمُونَ", "10": "يَاأَيُّهَا الَّذِينَ آمَنُوا إِذَا جَاءَكُمُ الْمُؤْمِنَاتُ مُهَاجِرَاتٍ فَامْتَحِنُوهُنَّ اللَّهُ أَعْلَمُ بِإِيمَانِهِنَّ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَاتٍ فَلَا تَرْجِعُوهُنَّ إِلَى الْكُفَّارِ لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ وَآتُوهُمْ مَا أَنْفَقُوا وَلَا جُنَاحَ عَلَيْكُمْ أَنْ تَنْكِحُوهُنَّ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ وَاسْأَلُوا مَا أَنْفَقْتُمْ وَلْيَسْأَلُوا مَا أَنْفَقُوا ذَلِكُمْ حُكْمُ اللَّهِ يَحْكُمُ بَيْنَكُمْ وَاللَّهُ عَلِيمٌ حَكِيمٌ", "11": "وَإِنْ فَاتَكُمْ شَيْءٌ مِنْ أَزْوَاجِكُمْ إِلَى الْكُفَّارِ فَعَاقَبْتُمْ فَآتُوا الَّذِينَ ذَهَبَتْ أَزْوَاجُهُمْ مِثْلَ مَا أَنْفَقُوا وَاتَّقُوا اللَّهَ الَّذِي أَنْتُمْ بِهِ مُؤْمِنُونَ", "12": "يَاأَيُّهَا النَّبِيُّ إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَادَهُنَّ وَلَا يَأْتِينَ بِبُهْتَانٍ يَفْتَرِينَهُ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ فَبَايِعْهُنَّ وَاسْتَغْفِرْ لَهُنَّ اللَّهَ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ", "13": "يَاأَيُّهَا الَّذِينَ آمَنُوا لَا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا مِنَ الْآخِرَةِ كَمَا يَئِسَ الْكُفَّارُ مِنْ أَصْحَابِ الْقُبُورِ"}, "units": [{"aya": 4, "title": "المراد بقوله تعالى: {والذين معه}", "mawsua": {"taliq": 6567, "masala": "المراد بقوله تعالى: {والذين معه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنهم أتباع الخليل إبراهيم الذين آمنوا معه", "ashab": "مقاتل", "athar": [76450]}, {"n": 2, "t": "أنهم الأنبياء الذين كانوا في عصره عليه السلام وقريبا من عصره", "ashab": "ابن زيد", "athar": [76451]}]}, "mawaqif": [{"taliq": 6567, "mi": 1, "aya": 4, "alam": "ابن كثير", "fil": "ذهب", "kind": "قول", "ref": "13/ 513", "qawl": "الأول", "nass": "", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 6567, "mi": 1, "aya": 4, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "22/ 566", "qawl": "الثاني", "nass": "", "qawaid": ["أقوال السلف"], "tabi": ""}, {"taliq": 6567, "mi": 1, "aya": 4, "alam": "ابن عطية", "fil": "رجحه", "kind": "ترجيح", "ref": "", "qawl": "الثاني", "nass": "وهذا القول أرجح؛ لأنه لم يرو أن إبراهيم كان له أتباع مؤمنون في مكافحته نمروذ، وفي البخاري أنه قال لسارة حين رحل بها إلى الشام مهاجرا من بلد النمرود: ما على الأرض من يعبد الله غيري وغيرك", "qawaid": ["السنة", "التاريخ والواقع"], "tabi": ""}], "tags": {"m": {"1": [["ابن كثير", "q"]], "2": [["ابن جرير", "q"], ["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن كثير": ["لم يذكر مستندًا"], "ابن جرير": ["أقوال السلف"], "ابن عطية": ["السنة", "التاريخ والواقع"]}, "rulesD": {}}}, {"aya": 8, "title": "في الذين عنوا بهذه الآية", "tabari": {"page": "22/571", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: عني بذلك: لا ينهاكم الله عن الذين لم يقاتلوكم في الدين من جميع أصناف الملل والأديان، أن تبروهم وتصلوهم وتقسطوا إليهم. إن الله ﷿ عم بقوله: ﴿الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم﴾ جميع من كان ذلك صفته، فلم يخصص به بعضا دون بعض. ولا معنى لقول من قال: ذلك منسوخ. لأن بر المؤمن من أهل الحرب ممن بينه وبينه قرابة نسب ، أو ممن لا قرابة بينه وبينه ولا نسب - غير محرم ولا منهي عنه، إذا لم يكن في ذلك دلالة له أو لأهل الحرب على عورة لأهل الإسلام، أو تقوية لهم بكراع أو سلاح. وقد بين صحة ما قلنا في ذلك الخبر الذي ذكرناه عن ابن الزبير في قصة أسماء وأمها.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "عني بها الذين كانوا آمنوا بمكة ولم يهاجروا، فأذن الله للمؤمنين ببرهم والإحسان إليهم", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [76483]}, {"n": 2, "t": "عني بها من غير أهل مكة من لم يهاجر", "taqdim": 0, "n_athar": 1, "qailun": [["لها", ""]], "athar": []}, {"n": 3, "t": "بل عني بها من مشركي مكة من لم يقاتل المؤمنين ولم يخرجوهم من ديارهم. قالوا: ونسخ الله ذلك بعد بالأمر بقتالهم", "taqdim": 0, "n_athar": 2, "qailun": [["قتادة", "تابعي"]], "athar": [76488]}]}, "mawaqif": [{"taliq": 6573, "mi": 1, "aya": 8, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "22/ 574", "qawl": "العموم", "nass": "أولى الأقوال في ذلك بالصواب قول من قال: عني بذلك: لا ينهاكم الله عن الذين لم يقاتلوكم في الدين من جميع أصناف الملل والأديان أن تبروهم وتصلوهم، وتقسطوا إليهم. إن الله عز وجل عم بقوله: {الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم} جميع من كان ذلك صفته، فلم يخصص به بعضا دون بعض", "qawaid": ["ظاهر الآية ولفظها", "أقوال السلف"], "tabi": ""}], "mushid": {"i": 1, "imgs": ["060_001_1.png"], "pages": [511], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 6573, "masala": "الذين عنوا بهذه الآية، واختلف أيضا في نسخها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "هم المؤمنون من أهل مكة الذين آمنوا ولم يهاجروا، وكانوا لذلك في رتبة سوء لتركهم فرض الهجرة", "ashab": "مجاهد", "athar": [76483]}, {"n": 2, "t": "أراد المؤمنين التاركين للهجرة كانوا من أهل مكة ومن غيرها", "ashab": "", "athar": []}, {"n": 3, "t": "أراد خزاعة، وبني الحارث بن كعب، وقبائل من العرب كفار، إلا أنهم كانوا مظاهرين للنبي صلى الله عليه وسلم محبين فيه وفي ظهوره، ومنهم كنانة، وبنو الحارث بن عبد مناة، ومزينة", "ashab": "الحسن، وأبو صالح", "athar": [76481, 76487]}, {"n": 4, "t": "أراد من كفار قريش من لم يقاتل، ولا أخرج، ولا أظهر سوءا. وعلى هذين القولين فالآية منسوخة بالقتال", "ashab": "", "athar": []}, {"n": 5, "t": "أراد النساء، والصبيان من الكفرة. وقال: إن الآية نزلت بسبب أم أسماء حين استأذنت النبي صلى الله عليه وسلم في برها وصلتها فأذن لها", "ashab": "عبد الله بن الزبير", "athar": [76478]}, {"n": 6, "t": "أراد المستضعفين من المؤمنين الذين لم يستطيعوا الهجرة", "ashab": "أبو جعفر بن النحاس، والثعلبي", "athar": []}, {"n": 7, "t": "نزلت في قوم من بني هاشم، منهم العباس?", "ashab": "مرة الهمداني، وعطية العوفي", "athar": [76479]}, {"n": 8, "t": "نسختها: {فاقتلوا المشركين حيث وجدتموهم} [التوبة: 5]", "ashab": "قتادة", "athar": [76488]}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "قال بـالعموم"]], "rules": {"ابن جرير": ["ظاهر الآية ولفظها", "أقوال السلف"]}, "rulesD": {}}}, {"aya": 11, "title": "في الكفار الذين عنوا بقوله: ﴿إلى الكفار﴾ من هم", "tabari": {"page": "22/588", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هم الكفار الذين لم يكن بينهم وبين رسول الله ﷺ عهد. قالوا: ومعنى الكلام: وإن فاتكم شيء من أزواجكم إلى من ليس بينكم وبينهم عهد من الكفار", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [76559, 76560, 76565, 76570, 76572, 76573, 76574, 76581]}, {"n": 2, "t": "بل هم كفار قريش الذين كانوا أهل هدنة، وذلك قول الزهري", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 2, "imgs": ["060_002_1.png"], "pages": [511], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في المال الذي أمر أن يعطى منه الذي ذهبت زوجته إلى المشركين", "tabari": {"page": "22/590", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك عندي بالصواب أن يقال: أمر الله ﷿ في هذه الآية المؤمنين أن يعطوا من فرت زوجته من المؤمنين إلى أهل الكفر إذا هم كانت لهم على أهل الكفر عقبى؛ إما بغنيمة يصيبونها منهم، أو بلحاق نساء بعضهم بهم - مثل الذي أنفقوا على الفارة منهم إليهم، ولم يخصص إيتاءهم ذلك من مال دون مال، فعليهم أن يعطوهم ذلك من كل الأموال التي ذكرناها.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "أمروا أن يعطوهم من صداق من لحق بهم من نساء المشركين", "taqdim": 0, "n_athar": 2, "qailun": [["الزهري", "تابعي"]], "athar": []}, {"n": 2, "t": "بل أمروا أن يعطوه من الغنيمة أو الفيء", "taqdim": 0, "n_athar": 8, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["مسروق", "تابعي"], ["إبراهيم", "تابعي"], ["ابن إسحاق", "تابع التابعين"]], "athar": [76559, 76560, 76563, 76564, 76565, 76567, 76568, 76569, 76570, 76572, 76573, 76574, 76581]}, {"n": 3, "t": "أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم﴾. قال: خرجت امرأة من أهل الإسلام إلى المشركين ولم يخرج غيرها. قال: فأتت امرأة من المشركين، فقال القوم: هذه عقبتكم قد أتتكم. فقال الله: ﴿وإن فاتكم شيء من أزواجكم إلى الكفار فعاقبتم﴾: أمسكتم الذي جاءكم منهم من أجل الذي لكم عندهم، ﴿فآتوا الذين ذهبت أزواجهم مثل ما أنفقوا﴾. ثم أخبرهم الله أنه لا جناح عليهم إذا فعلوا الذي فعلوا، أن ينكحو", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 6585, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "8/ 285", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6585, "mi": 1, "aya": 11, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 285", "qawl": "الأول", "nass": "هذا قول صحيح، يقتضيه قوله تعالى: {فعاقبتم}", "qawaid": [], "tabi": ""}, {"taliq": 6585, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "22/ 593", "qawl": "العموم", "nass": "أولى الأقوال في ذلك بالصواب أن يقال: أمر الله عز وجل في هذه الآية المؤمنين أن يعطوا من فرت زوجته من المؤمنين إلى أهل الكفر -إذا هم كانت لهم على أهل الكفر عقبى: إما بغنيمة يصيبونها منهم، أو بلحاق نساء بعضهم بهم- مثل الذي أنفقوا على الفارة منهم إليهم، ولم يخصص إيتاءهم ذلك من مال دون مال، فعليهم أن يعطوهم ذلك من كل الأموال التي ذكرناها", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 6585, "mi": 1, "aya": 11, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 525", "qawl": "", "nass": "هذا لا ينافي الأول؛ لأنه إن أمكن الأول فهو أولى، وإلا فمن الغنائم اللاتي تؤخذ من أيدي الكفار، وهذا أوسع وهو اختيار ابن جرير", "qawaid": [], "tabi": ""}, {"taliq": 6585, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "وهو اختيار", "kind": "موافقة", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن كثير"}], "mushid": {"i": 3, "imgs": ["060_003_1.png", "060_003_2.png"], "pages": [511, 512], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 6585, "masala": "المال الذي أمر أن يعطى منه الذي ذهبت زوجته إلى المشركين", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "يعطى من صداق من أسلمن منهن عن زوج كافر", "ashab": "الزهري", "athar": []}, {"n": 2, "t": "يعطى من أموال غنائمهم لاستحقاقها عليهم", "ashab": "ابن عباس، ومجاهد، وقتادة", "athar": [76567, 76568, 76570, 76572, 76573, 76574, 76581]}, {"n": 3, "t": "يعطى من أي وجوه الفيء أمكن", "ashab": "ثان للزهري", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "قال بـالعموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 13, "title": "في تأويل قوله: ﴿قد يئسوا من الآخرة كما يئس الكفار من أصحاب القبور﴾", "tabari": {"page": "22/602", "sarih": 1, "tarjih": "وأولى القولين في ذلك عندي بالصواب قول من قال: قد يئس هؤلاء الذين غضب الله عليهم من اليهود، من ثواب الله لهم في الآخرة وكرامته؛ لكفرهم وتكذيبهم رسوله محمدا ﷺ، على علم منهم بأنه لله نبي، كما يئس الكفار منهم الذين مضوا قبلهم فهلكوا، فصاروا أصحاب القبور، وهم على مثل الذي هؤلاء عليه، من تكذيبهم عيسى صلوات الله عليه، وغيره من الرسل - من ثواب الله وكرامته إياهم.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معنى ذلك: قد يئس هؤلاء القوم الذين غضب الله عليهم من اليهود، من ثواب الله لهم في الآخرة، وأن يبعثوا، كما يئس الكفار الأحياء من أمواتهم الذين هم في القبور أن يرجعوا إليهم", "taqdim": 0, "n_athar": 5, "qailun": [["ابن عباس", "صحابي"], ["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": [76637, 76639, 76640, 76641, 76646, 76653, 76655, 76656]}, {"n": 2, "t": "بل معنى ذلك: قد يئسوا من الآخرة أن يرحمهم الله فيها، أو يغفر لهم، كما يئس الكفار الذين هم أصحاب قبور قد ماتوا، وصاروا إلى القبور، من رحمة الله وعفوه عنهم في الآخرة؛ لأنهم قد أيقنوا بعذاب الله لهم", "taqdim": 0, "n_athar": 6, "qailun": [["مجاهد في هذه الآية", "تابعي"], ["مجاهد", "تابعي"], ["عكرمة", "تابعي"], ["معمر", "تابع التابعين"], ["ابن زيد", "تابع التابعين"], ["منصور", ""]], "athar": [76644, 76648, 76649, 76650, 76657, 76660]}]}, "mawaqif": [{"taliq": 6593, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 289 - 290", "qawl": "", "nass": "من قال: إن القوم المشار إليهم: هم كفار مكة. قال: معنى قوله: {كما يئس الكفار} كما يئس الكافر من صاحب قبر؛ لأنه إذا مات له حميم قال: هذا آخر العهد به، لن يبعث أبدا. فمعنى الآية: أن اعتقاد أهل مكة في الآخرة كاعتقاد الكافر في البعث ولقاء موتاه. وهذا هو تأويل ابن عباس، والحسن، وقتادة في معنى قوله تعالى: {كما يئس الكفار}، ومن قال: إن القوم المشار إليهم: هم اليهود. قال: معنى قوله: {كما يئس الكفار} أي: كما يئس الكافر من الرحمة إذا مات، وكان صاحب قبر، وذلك أنه يروى أن الكافر إذا كان في قبره عرض عليه مقعده في الجنة أن لو كان مؤمنا، ثم يعرض عليه مقعده من النار الذي يصير إليه، فهو يائس من رحمة الله مع علمه بها ويقينه. وهذا تأويل مجاهد، وابن جبير، وابن زيد في قوله: {كما يئس الكفار} فمعنى الآية: أن يأس اليهود من رحمة الله في الآخرة مع علمهم بها كيأس ذلك الكافر في قبره، وذلك لأنهم قد رين على قلوبهم، وحملهم الحسد على ترك الإيمان، وغلب على ظنونهم أنهم معذبون، وهذه كانت صفة كثير من معاصري النبي صلى الله ع", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 6593, "mi": 0, "aya": 13, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "22/ 605", "qawl": "الثاني", "nass": "أولى القولين في ذلك عندي بالصواب قول من قال: قد يئس هؤلاء الذين غضب الله عليهم من اليهود من ثواب الله لهم في الآخرة وكرامته؛ لكفرهم وتكذيبهم رسوله محمدا صلى الله عليه وسلم على علم منهم بأنه لله نبي، كما يئس الكفار منهم الذين مضوا قبلهم فهلكوا، فصاروا أصحاب القبور، وهم على مثل الذي هؤلاء عليه، من تكذيبهم عيسى -صلوات الله عليه- وغيره من الرسل، من ثواب الله وكرامته إياهم. وإنما قلنا: ذلك أولى القولين بتأويل الآية. لأن الأموات قد يئسوا من رجوعهم إلى الدنيا، أو أن يبعثوا قبل قيام الساعة المؤمنون والكفار، فلا وجه لأن يخص بذلك الخبر عن الكفار، وقد شركهم في الإياس من ذلك المؤمنون", "qawaid": ["الدلالة العقلية"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["060_004_1.png", "060_004_2.png"], "pages": [512, 513], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"], "ابن جرير": ["الدلالة العقلية"]}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 6558, "kinds": "نقل", "text": "نقل ابنُ عطية الإجماعَ على مَدَنِيّة سورة الممتحنة، فقال (8/ 276): «هي مدنية بإجماع من المفسرين».\nوقد نُصَّ على مدنية السورة أيضًا في تفسير ابن كثير (13/ 506).", "mawaqif": [{"taliq": 6558, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "", "qawl": "", "nass": "هي مدنية بإجماع من المفسرين", "qawaid": [], "tabi": ""}]}], "1": [{"id": 6559, "kinds": "نقل", "text": "ذَكَرَ ابنُ جرير (22/ 559)، وابنُ عطية (8/ 276)، وابنُ تيمية (6/ 283)، وابنُ كثير (13/ 506) أنّ سبب نزول هذه الآية: قصة حاطِب بن أبي بَلْتَعة.\nوقال ابنُ تيمية (6/ 284): «هذه القصة مما اتفق أهل العلم على صحّتها، وهي متواترة عندهم، معروفة عند علماء التفسير، وعلماء الحديث، وعلماء المغازي والسِّير والتواريخ، وعلماء الفقه، وغير هؤلاء، وكان علي رضي الله عنهما يحدِّث بهذا الحديث في خلافته بعد الفتنة، وروى ذلك عنه كاتبُه عبد الله بن أبي رافع ليُبيّن [لهم] أنّ السابقين مغفور لهم، ولو جرى منهم ما جرى».", "mawaqif": [{"taliq": 6559, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "22/ 559", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6559, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "8/ 276", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 6559, "mi": 0, "aya": 1, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 284", "qawl": "", "nass": "هذه القصة مما اتفق أهل العلم على صحتها، وهي متواترة عندهم، معروفة عند علماء التفسير، وعلماء الحديث، وعلماء المغازي والسير والتواريخ، وعلماء الفقه، وغير هؤلاء، وكان علي رضي الله عنهما يحدث بهذا الحديث في خلافته بعد الفتنة، وروى ذلك عنه كاتبه عبد الله بن أبي رافع ليبين [لهم] أن السابقين مغفور لهم، ولو جرى منهم ما جرى", "qawaid": [], "tabi": ""}]}, {"id": 6560, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 276): «العدُوّ: اسم يقع للجمع والمفرد، والمراد به هاهنا: كفار قريش».", "mawaqif": [{"taliq": 6560, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 276", "qawl": "", "nass": "العدو: اسم يقع للجمع والمفرد، والمراد به هاهنا: كفار قريش", "qawaid": [], "tabi": ""}]}, {"id": 6561, "kinds": "غيره", "text": "قال ابنُ جرير (22/ 557): «دخول الباء في قوله: {بالمودة} وسقوطها سواء، نظير قول القائل: أريد بأن تذهب، وأريد أن تذهب. سواء، وكقوله: {ومن يرد فيه بإلحاد بظلم} [الحج: 25] والمعنى: ومن يرد فيه إلحادًا بظلم».\nوبنحوه قال ابنُ عطية (8/ 277).", "mawaqif": [{"taliq": 6561, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "22/ 557", "qawl": "", "nass": "دخول الباء في قوله: {بالمودة} وسقوطها سواء، نظير قول القائل: أريد بأن تذهب، وأريد أن تذهب. سواء، وكقوله: {ومن يرد فيه بإلحاد بظلم} [الحج: 25] والمعنى: ومن يرد فيه إلحادا بظلم", "qawaid": [], "tabi": ""}, {"taliq": 6561, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 277", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}, {"id": 6562, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 278): «قوله تعالى: {إن كنتم} شرطٌ، جوابه متقدم في معنى ما قبله، وجاز ذلك لِما لم يظهر عمل الشرط، والتقدير: إن كنتم خرجتم جهادًا في سبيلي، وابتغاء مرضاتي؛ فلا تتخذوا عدوي وعدوكم أولياء».\nوبنحوه قال ابنُ جرير (22/ 558).", "mawaqif": [{"taliq": 6562, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 278", "qawl": "", "nass": "قوله تعالى: {إن كنتم} شرط، جوابه متقدم في معنى ما قبله، وجاز ذلك لما لم يظهر عمل الشرط، والتقدير: إن كنتم خرجتم جهادا في سبيلي، وابتغاء مرضاتي؛ فلا تتخذوا عدوي وعدوكم أولياء", "qawaid": [], "tabi": ""}, {"taliq": 6562, "mi": 0, "aya": 1, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "22/ 558", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}]}, {"id": 6563, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 278): «قوله تعالى: {أعلم} يحتمل أن يكون: أفْعَل، ويحتمل أنْ يكون فِعْلًا؛ لأنك تقول: علمت بكذا. فتدخل الباء».", "mawaqif": [{"taliq": 6563, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 278", "qawl": "", "nass": "قوله تعالى: {أعلم} يحتمل أن يكون: أفعل، ويحتمل أن يكون فعلا؛ لأنك تقول: علمت بكذا. فتدخل الباء", "qawaid": [], "tabi": ""}]}, {"id": 6564, "kinds": "نقل", "text": "قال ابنُ كثير (13/ 511): «قال تعالى: {لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء إلا أن تتقوا منهم تقاة ويحذركم الله نفسه} [آل عمران: 28]، ولهذا قَبِلَ رسول الله صلى الله عليه وسلم عُذْرَ حاطِب، لما ذَكر أنه إنما فعل ذلك مصانعة لقريش لأجل ما كان له عندهم من الأموال والأولاد».", "mawaqif": [{"taliq": 6564, "mi": 0, "aya": 1, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 511", "qawl": "", "nass": "قال تعالى: {لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين ومن يفعل ذلك فليس من الله في شيء إلا أن تتقوا منهم تقاة ويحذركم الله نفسه} [آل عمران: 28]، ولهذا قبل رسول الله صلى الله عليه وسلم عذر حاطب، لما ذكر أنه إنما فعل ذلك مصانعة لقريش لأجل ما كان له عندهم من الأموال والأولاد", "qawaid": [], "tabi": ""}]}], "4": [{"id": 6565, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 280): «قوله: {كفرنا بكم} أي: كذبناكم في أقوالكم، ولم نؤمن بشيء منها. ونظير هذا قوله عليه السلام حكاية عن قول الله عز وجل: «فهو مُؤمِن بي، كافِرٌ بالكوكب»».", "mawaqif": [{"taliq": 6565, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 280", "qawl": "", "nass": "قوله: {كفرنا بكم} أي: كذبناكم في أقوالكم، ولم نؤمن بشيء منها. ونظير هذا قوله عليه السلام حكاية عن قول الله عز وجل: «فهو مؤمن بي، كافر بالكوكب»", "qawaid": [], "tabi": ""}]}, {"id": 6566, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 279): «هذه الأسوة مقيّدة في التبرّي مِن الإشراك، وهو مُطَّرد في كلِّ ملَّة، وفي نبيّنا صلى الله عليه وسلم أُسوة حسنة على الإطلاق؛ لأنها في العقائد، وفي أحكام الشرع كلّها».", "mawaqif": [{"taliq": 6566, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 279", "qawl": "", "nass": "هذه الأسوة مقيدة في التبري من الإشراك، وهو مطرد في كل ملة، وفي نبينا صلى الله عليه وسلم أسوة حسنة على الإطلاق؛ لأنها في العقائد، وفي أحكام الشرع كلها", "qawaid": [], "tabi": ""}]}], "5": [{"id": 6568, "kinds": "ترجيح،نقد،تعليق", "text": "عَلَّقَ ابنُ عطية (8/ 281) على قول ابن عباس، فقال: «كأنه قال: لا تجعلنا مفتونين. فعبّر عن ذلك بالمصدر». ثم رَجَّحَ هذا القول، وانتقد قول قتادة استنادًا للدلالة العقلية، والنظير، فقال: «وهذا أرجح الأقوال؛ لأنّهم إنما دَعوا لأنفسهم، وعلى منحى قتادة إنما دَعوا للكفار. أما إن مقصدهم إنما هو أن يندفع عنهم ظهور الكفار الذي بسببه فُتِن الكفار، فجاء في المعنى تحليق بليغ، ونحوه قول النبي صلى الله عليه وسلم: «بئس الميت سعد» ليهود؛ لأنهم يقولون: لو كان محمد نبيًّا لم يمت صاحبه».", "mawaqif": [{"taliq": 6568, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 281", "qawl": "ابن عباس", "nass": "كأنه قال: لا تجعلنا مفتونين. فعبر عن ذلك بالمصدر", "qawaid": ["الدلالة العقلية", "غير ذلك"], "tabi": ""}]}, {"id": 6569, "kinds": "غيره", "text": "ذهب ابنُ جرير (22/ 569) -مستندًا إلى أقوال السلف- إلى مثل ما ذهب إليه قتادة في تفسير قوله تعالى: {رَبَّنا لا تَجْعَلْنا فِتْنَةً لِلَّذِينَ كَفَرُوا}.", "mawaqif": [{"taliq": 6569, "mi": 0, "aya": 5, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "22/ 569", "qawl": "", "nass": "", "qawaid": ["أقوال السلف"], "tabi": ""}]}], "7": [{"id": 6570, "kinds": "نقل", "text": "قالَ ابن عطية (8/ 281 - 282): «رُوي أن هذه الآيات لما نَزَلَتْ، وأزمع المؤمنون امتثال أمرها، وصَرم حبال الكفرة، وإظهار عداوتهم؛ لحقهم تأسّفٌ على قراباتهم، وهم مَن أن لم يؤمنوا ولم يهتدوا حتى يكون بينهم الود والتواصل، فنَزلت: {عسى الله} الآية مُؤْنسةً في ذلك ومُرَجِّيةً أن يقع موقع ذلك بإسلامهم في الفتح، وصار الجميع إخوانًا».", "mawaqif": [{"taliq": 6570, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 281 - 282", "qawl": "", "nass": "روي أن هذه الآيات لما نزلت، وأزمع المؤمنون امتثال أمرها، وصرم حبال الكفرة، وإظهار عداوتهم؛ لحقهم تأسف على قراباتهم، وهم من أن لم يؤمنوا ولم يهتدوا حتى يكون بينهم الود والتواصل، فنزلت: {عسى الله} الآية مؤنسة في ذلك ومرجية أن يقع موقع ذلك بإسلامهم في الفتح، وصار الجميع إخوانا", "qawaid": [], "tabi": ""}]}, {"id": 6571, "kinds": "تعليق", "text": "عَلَّقَ ابن عطية (8/ 282) على هذا الأثر بقوله: «لا يصح ذلك عن ابن عباس إلا أن يسوقه مثالًا، وإن كان متقدمًا لهذه الآية؛ لأنه استمر بعد الفتح كسائر ما نشأ من المودّات».", "mawaqif": [{"taliq": 6571, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 282", "qawl": "", "nass": "لا يصح ذلك عن ابن عباس إلا أن يسوقه مثالا، وإن كان متقدما لهذه الآية؛ لأنه استمر بعد الفتح كسائر ما نشأ من المودات", "qawaid": [], "tabi": ""}]}, {"id": 6572, "kinds": "نقد،بيان،نقل", "text": "انتَقَدَ ابنُ عطية، وابنُ كثير هذا القول استنادًا إلى التاريخ، فقال ابنُ عطية (8/ 282): «مَن ذَكَر أنّ هذه المودة تزويج النبي صلى الله عليه وسلم أُمّ حَبيبة بنت أبي سُفيان، وأنها كانت بعد الفتح، فقد أخطأ؛ لأن النبي صلى الله عليه وسلم تزوّجها وقت هجرة الحبشة، وهذه الآيات نَزَلَتْ سنة ثمانٍ من الهجرة».\nوقال ابنُ كثير (13/ 216) تعليقًا على أثر مقاتل هذا: «وفي هذا الذي قاله مقاتل نظر؛ فإنّ رسول الله صلى الله عليه وسلم تزوّج بأُمّ حبيبة بنت أبي سُفيان قبل الفتح، وأبو سُفيان إنما أسلم ليلة الفتح بلا خلاف». ثم بَيَّنَ أنّ أثر الزُّهريّ -السابق- أحسن منه.", "mawaqif": [{"taliq": 6572, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "", "qawl": "استنادا إلى", "nass": "", "qawaid": ["التاريخ والواقع"], "tabi": ""}, {"taliq": 6572, "mi": 0, "aya": 7, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "", "qawl": "استنادا إلى", "nass": "", "qawaid": ["التاريخ والواقع"], "tabi": "ابن عطية"}, {"taliq": 6572, "mi": 0, "aya": 7, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 282", "qawl": "", "nass": "من ذكر أن هذه المودة تزويج النبي صلى الله عليه وسلم أم حبيبة بنت أبي سفيان، وأنها كانت بعد الفتح، فقد أخطأ؛ لأن النبي صلى الله عليه وسلم تزوجها وقت هجرة الحبشة، وهذه الآيات نزلت سنة ثمان من الهجرة", "qawaid": [], "tabi": ""}, {"taliq": 6572, "mi": 0, "aya": 7, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 216", "qawl": "", "nass": "وفي هذا الذي قاله مقاتل نظر؛ فإن رسول الله صلى الله عليه وسلم تزوج بأم حبيبة بنت أبي سفيان قبل الفتح، وأبو سفيان إنما أسلم ليلة الفتح بلا خلاف", "qawaid": [], "tabi": ""}]}], "9": [{"id": 6574, "kinds": "بيان", "text": "قال ابنُ عطية (8/ 283): «الذين قاتلوا في الدّين وأَخْرَجوا: هم مَرَدة قريش».\nوقال ابنُ القيم (3/ 149): «الله سبحانه لمّا نهى في أول السورة عن اتخاذ المسلمين الكفار أولياء، وقطع المودة بينهم وبينهم؛ تَوهَّم بعضُهم أنّ برَّهم والإحسان إليهم من الموالاة والمودّة، فبيَّن الله سبحانه أنّ ذلك ليس مِن الموالاة المنهي عنها، وأنه لم يَنْهَ عن ذلك، بل هو من الإحسان الذي يحبّه ويرضاه، وكتبه على كلّ شيء، وإنما المنهيّ عنه تَولّي الكفار، والإلقاء إليهم بالمودّة».", "mawaqif": [{"taliq": 6574, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 283", "qawl": "", "nass": "الذين قاتلوا في الدين وأخرجوا: هم مردة قريش", "qawaid": [], "tabi": ""}, {"taliq": 6574, "mi": 0, "aya": 9, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "3/ 149", "qawl": "", "nass": "الله سبحانه لما نهى في أول السورة عن اتخاذ المسلمين الكفار أولياء، وقطع المودة بينهم وبينهم؛ توهم بعضهم أن برهم والإحسان إليهم من الموالاة والمودة، فبين الله سبحانه أن ذلك ليس من الموالاة المنهي عنها، وأنه لم ينه عن ذلك، بل هو من الإحسان الذي يحبه ويرضاه، وكتبه على كل شيء، وإنما المنهي عنه تولي الكفار، والإلقاء إليهم بالمودة", "qawaid": [], "tabi": ""}]}], "10": [{"id": 6575, "kinds": "تعليق", "text": "عَلَّقَ ابنُ كثير (13/ 520) على هذه الرواية بقوله: «على هذه الرواية تكون هذه الآية مخصّصة للسنة، وهذا من أحسن أمثلة ذلك. وعلى طريقة بعض السلف ناسخة، فإنّ الله عز وجل أمر عباده المؤمنين إذا جاءهم النساء مُهاجرات أن يَمتَحِنوهن، فإنْ علموهنّ مؤمنات فلا يرجعوهنّ إلى الكفار، لا هُنّ حِلٌّ لهم ولا هم يَحلّون لهنّ».", "mawaqif": [{"taliq": 6575, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 520", "qawl": "", "nass": "على هذه الرواية تكون هذه الآية مخصصة للسنة، وهذا من أحسن أمثلة ذلك. وعلى طريقة بعض السلف ناسخة، فإن الله عز وجل أمر عباده المؤمنين إذا جاءهم النساء مهاجرات أن يمتحنوهن، فإن علموهن مؤمنات فلا يرجعوهن إلى الكفار، لا هن حل لهم ولا هم يحلون لهن", "qawaid": [], "tabi": ""}]}, {"id": 6576, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 283) تعليقًا على هذه الآية: «نَزَلَتْ إثر صُلح الحُدَيبية، وذلك أنّ الصُّلح تضمّن أن يَردّ المؤمنون إلى الكفار كلَّ من جاء مسلمًا مِن رجل وامرأة، فنقض الله تعالى من ذلك أمر النساء بهذه الآية، وحكم أنّ المُهاجِرة لا تُردّ إلى الكفار، بل تبقى تستبرئ وتتزوّج ويُعطى زوجها الكافر الصداق الذي أنفق، وأمر أيضًا المؤمنين بطلب صداق مَن فرَّت امرأتُه مِن المؤمنين، وحكم تعالى بهذا في النازلة وسمّاهم: مؤمنات قبل أن يتيقّن ذلك؛ إذ هو ظاهر أمرهن».\nوبنحوه قال ابنُ جرير (22/ 578)، وقال ابنُ تيمية (6/ 292)، وقال ابنُ القيم (3/ 150).", "mawaqif": [{"taliq": 6576, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 283", "qawl": "", "nass": "نزلت إثر صلح الحديبية، وذلك أن الصلح تضمن أن يرد المؤمنون إلى الكفار كل من جاء مسلما من رجل وامرأة، فنقض الله تعالى من ذلك أمر النساء بهذه الآية، وحكم أن المهاجرة لا ترد إلى الكفار، بل تبقى تستبرئ وتتزوج ويعطى زوجها الكافر الصداق الذي أنفق، وأمر أيضا المؤمنين بطلب صداق من فرت امرأته من المؤمنين، وحكم تعالى بهذا في النازلة وسماهم: مؤمنات قبل أن يتيقن ذلك؛ إذ هو ظاهر أمرهن", "qawaid": [], "tabi": ""}, {"taliq": 6576, "mi": 0, "aya": 10, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "22/ 578", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 6576, "mi": 0, "aya": 10, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 292", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 6576, "mi": 0, "aya": 10, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "3/ 150", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 6577, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 283): «قوله تعالى: {الله أعلم بإيمانهن} إشارة إلى الاسترابة ببعضهن، وحضّ على امتحانهنّ، وذكر تعالى العِلّة في أن لا يُرَدّ النساء إلى الكفار وهي امتناع الوطء وحرمته».", "mawaqif": [{"taliq": 6577, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 283", "qawl": "", "nass": "قوله تعالى: {الله أعلم بإيمانهن} إشارة إلى الاسترابة ببعضهن، وحض على امتحانهن، وذكر تعالى العلة في أن لا يرد النساء إلى الكفار وهي امتناع الوطء وحرمته", "qawaid": [], "tabi": ""}]}, {"id": 6578, "kinds": "غيره", "text": "قال ابن كثير (13/ 521): «قوله تعالى: {فإن علمتموهن مؤمنات فلا ترجعوهن إلى الكفار} فيه دلالة على أنّ الإيمان يُمكن الاطلاع عليه يقينًا».", "mawaqif": [{"taliq": 6578, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 521", "qawl": "", "nass": "قوله تعالى: {فإن علمتموهن مؤمنات فلا ترجعوهن إلى الكفار} فيه دلالة على أن الإيمان يمكن الاطلاع عليه يقينا", "qawaid": [], "tabi": ""}]}, {"id": 6579, "kinds": "نقد", "text": "قال ابنُ كثير (13/ 521): «قوله تعالى: {لا هن حل لهم ولا هم يحلون لهن} هذه الآية هي التي حَرّمت المسلمات على المشركين، وقد كان جائزًا في ابتداء الإسلام أن يتزوّج المشرك المؤمنة، ولهذا كان أبو العاص بن الربيع زوج ابنة النبي صلى الله عليه وسلم زينب رضي الله عنها، قد كانت مُسلمة وهو على دين قومه، فلما وقع في الأسارى يوم بدر بعثت امرأته زينب في فدائه بقِلادة لها كانت لأُمّها خديجة، فلمّا رآها رسول الله صلى الله عليه وسلم رقَّ لها رِقّة شديدة، وقال للمسلمين: «إن رأيتم أن تطلقوا لها أسيرها فافعلوا». ففعلوا، فأطلقه رسول الله صلى الله عليه وسلم على أن يبعث ابنته إليه، فوفّى له بذلك، وصدقه فيما وعده، وبعثها إلى رسول الله صلى الله عليه وسلم مع زيد بن حارثة رضي الله عنهما، فأقامت بالمدينة مِن بعد وقعة بدر، وكانت سنة اثنتين، إلى أنْ أسلم زوجها أبو العاص بن الربيع سنة ثمانٍ، فردَّها عليه بالنكاح الأول، ولم يُحدث لها صداقًا».", "mawaqif": [{"taliq": 6579, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 521", "qawl": "", "nass": "قوله تعالى: {لا هن حل لهم ولا هم يحلون لهن} هذه الآية هي التي حرمت المسلمات على المشركين، وقد كان جائزا في ابتداء الإسلام أن يتزوج المشرك المؤمنة، ولهذا كان أبو العاص بن الربيع زوج ابنة النبي صلى الله عليه وسلم زينب رضي الله عنها، قد كانت مسلمة وهو على دين قومه، فلما وقع في الأسارى يوم بدر بعثت امرأته زينب في فدائه بقلادة لها كانت لأمها خديجة، فلما رآها رسول الله صلى الله عليه وسلم رق لها رقة شديدة، وقال للمسلمين: «إن رأيتم أن تطلقوا لها أسيرها فافعلوا", "qawaid": [], "tabi": ""}]}, {"id": 6580, "kinds": "نقد", "text": "قال ابنُ القيم (3/ 150): «في هذا دليلٌ على أنّ خروج البُضع مِن ملك الزوج متقوّم، وأنه متقوّم بالمُسمّى الذي هو ما أنفق الزوج لا بمهر المثل، وأنّ أنكحة الكفار لها حكم الصحة، لا يُحكم عليها بالبطلان، وأنه لا يجوز ردّ المسلمة المُهاجِرة إلى الكفار ولو شُرط ذلك، وأنّ المسلمة لا يحلّ لها نكاح الكافر، وأنّ المسلم له أن يتزوج المرأة المُهاجِرة إذا انقضت عِدّتها، وآتاها مهرها، وفي هذا أبين دلالة على خروج بُضعها من ملك الزوج، وانفساخ نكاحها منه بالهجرة والإسلام، وفيه دليل على تحريم نكاح المشركة على المسلم، كما حرم نكاح المسلمة على الكافر».\nوبنحوه قال ابنُ تيمية (6/ 292).", "mawaqif": [{"taliq": 6580, "mi": 0, "aya": 10, "alam": "ابن القيم", "fil": "قال", "kind": "قول", "ref": "3/ 150", "qawl": "", "nass": "في هذا دليل على أن خروج البضع من ملك الزوج متقوم، وأنه متقوم بالمسمى الذي هو ما أنفق الزوج لا بمهر المثل، وأن أنكحة الكفار لها حكم الصحة، لا يحكم عليها بالبطلان، وأنه لا يجوز رد المسلمة المهاجرة إلى الكفار ولو شرط ذلك، وأن المسلمة لا يحل لها نكاح الكافر، وأن المسلم له أن يتزوج المرأة المهاجرة إذا انقضت عدتها، وآتاها مهرها، وفي هذا أبين دلالة على خروج بضعها من ملك الزوج، وانفساخ نكاحها منه بالهجرة والإسلام، وفيه دليل على تحريم نكاح المشركة على المسلم، كما حرم نكاح المسلمة على الكافر", "qawaid": [], "tabi": ""}, {"taliq": 6580, "mi": 0, "aya": 10, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 292", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن القيم"}]}, {"id": 6581, "kinds": "خلاف،بيان", "text": "بَيَّنَ ابنُ عطية (8/ 284) أنّ في تأويل {الكوافر} في هذه الآية قولين، فقال: «قيل: الآيات في عابدات الأوثان ومَن لا يجوز نكاحها ابتداء. وقيل: هي عامة نسخ منها نساء أهل الكتاب».\nوذهب ابنُ جرير (22/ 583) مستندًا إلى أقوال السلف، وبنحوه ابنُ تيمية (6/ 292) إلى القول الأول.", "mawaqif": [{"taliq": 6581, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "8/ 284", "qawl": "", "nass": "قيل: الآيات في عابدات الأوثان ومن لا يجوز نكاحها ابتداء. وقيل: هي عامة نسخ منها نساء أهل الكتاب", "qawaid": [], "tabi": ""}, {"taliq": 6581, "mi": 0, "aya": 10, "alam": "ابن جرير", "fil": "ذهب", "kind": "قول", "ref": "22/ 583", "qawl": "الأول", "nass": "", "qawaid": ["أقوال السلف", "اللغة"], "tabi": ""}, {"taliq": 6581, "mi": 0, "aya": 10, "alam": "ابن تيمية", "fil": "وبنحوه", "kind": "موافقة", "ref": "6/ 292", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}]}, {"id": 6582, "kinds": "غيره", "text": "قال ابنُ تيمية (6/ 290): «قوله: {ولا تُمْسِكُوا بِعِصَمِ الكَوافِرِ} إنما يتناول النكاح، لا يتناول الوطء بمِلك اليمين».", "mawaqif": [{"taliq": 6582, "mi": 0, "aya": 10, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 290", "qawl": "", "nass": "قوله: {ولا تمسكوا بعصم الكوافر} إنما يتناول النكاح، لا يتناول الوطء بملك اليمين", "qawaid": [], "tabi": ""}]}, {"id": 6583, "kinds": "نقد،بيان", "text": "انتقد ابنُ القيم (3/ 150) القول بالنسخ في الآية؛ لعدم الدليل عليه: «ليس مع مَن ادعى نَسْخها حُجّة ألبتة؛ فإنّ الشرط الذي وقع بين النبي صلى الله عليه وسلم وبين الكفار في ردّ مَن جاءه مسلمًا إليهم إن كان مختصًا بالرجال لم تدخل النساء فيه، وإن كان عامًّا للرجال والنساء فالله? خصّص منه ردّ النساء ونهاهم عن ردهنّ، وأمرهم بردّ مهورهنّ، وأن يَردّوا منها على مَن ارتدت امرأته إليهم من المسلمين المهر الذي أعطاها، ثم أخبر أنّ ذلك حكمه الذي يحكم به بين عباده، وأنه صادر عن عِلْمه وحِكمته، ولم يأت عنه ما ينافي هذا الحكم، ويكون بعده حتى يكون ناسخًا».", "mawaqif": [{"taliq": 6583, "mi": 0, "aya": 10, "alam": "ابن القيم", "fil": "انتقد", "kind": "نقد", "ref": "3/ 150", "qawl": "بالنسخ في", "nass": "ليس مع من ادعى نسخها حجة ألبتة؛ فإن الشرط الذي وقع بين النبي صلى الله عليه وسلم وبين الكفار في رد من جاءه مسلما إليهم إن كان مختصا بالرجال لم تدخل النساء فيه، وإن كان عاما للرجال والنساء فالله? خصص منه رد النساء ونهاهم عن ردهن، وأمرهم برد مهورهن، وأن يردوا منها على من ارتدت امرأته إليهم من المسلمين المهر الذي أعطاها، ثم أخبر أن ذلك حكمه الذي يحكم به بين عباده، وأنه صادر عن علمه وحكمته، ولم يأت عنه ما ينافي هذا الحكم، ويكون بعده حتى يكون ناسخا", "qawaid": [], "tabi": ""}]}], "11": [{"id": 6584, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 285): «المعاقبة في هذه الآية ليست بمعنى: مجازاة السوء بالسوء، ولكنها بمعنى: فصرتم منهم إلى الحال التي صاروا إليها منكم، وذلك بأن يفوت إليكم شيء من أزواجكم، وهكذا هو التعقيب على الحمل والدواب؛ أن يركب هذا عُقْبة ويركب هذا عُقْبة».", "mawaqif": [{"taliq": 6584, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 285", "qawl": "", "nass": "المعاقبة في هذه الآية ليست بمعنى: مجازاة السوء بالسوء، ولكنها بمعنى: فصرتم منهم إلى الحال التي صاروا إليها منكم، وذلك بأن يفوت إليكم شيء من أزواجكم، وهكذا هو التعقيب على الحمل والدواب؛ أن يركب هذا عقبة ويركب هذا عقبة", "qawaid": [], "tabi": ""}]}, {"id": 6586, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 283): «هذه الآية كلها قد ارتفع حكمها، ثم ندب تعالى إلى التقوى وأوجبها، وذكر العلة التي بها يجب التقوى، وهي الإيمان بالله والتصديق بوحدانيته وصفاته وعقابه وإنعامه».", "mawaqif": [{"taliq": 6586, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 283", "qawl": "", "nass": "هذه الآية كلها قد ارتفع حكمها، ثم ندب تعالى إلى التقوى وأوجبها، وذكر العلة التي بها يجب التقوى، وهي الإيمان بالله والتصديق بوحدانيته وصفاته وعقابه وإنعامه", "qawaid": [], "tabi": ""}]}], "12": [{"id": 6587, "kinds": "غيره", "text": "قال ابنُ كثير (13/ 530): «هذا أثر غريب، وفي بعضه نكارة، والله أعلم؛ فإن أبا سفيان وامرأته لما أسلما لم يكن رسول الله يخيفهما، بل أظهرا الصفاء والودّ لهما، وكذلك كان الأمر من جانبه عليه السلام لهما».", "mawaqif": [{"taliq": 6587, "mi": 0, "aya": 12, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 530", "qawl": "", "nass": "هذا أثر غريب، وفي بعضه نكارة، والله أعلم؛ فإن أبا سفيان وامرأته لما أسلما لم يكن رسول الله يخيفهما، بل أظهرا الصفاء والود لهما، وكذلك كان الأمر من جانبه عليه السلام لهما", "qawaid": [], "tabi": ""}]}, {"id": 6588, "kinds": "خلاف،تعليق،نقل", "text": "قال ابنُ عطية (8/ 287 - 288): «اختَلفت هيئات مبايعة رسول الله صلى الله عليه وسلم النساء بعد الإجماع على أنه لم تمسّ يده يد امرأة أجنبية، فيُروى عن عائشة وغيرها أنه بايع باللسان قولًا، وقال: «إنما قَوْلي لمائة امرأة كقَوْلي لامرأة واحدة». وقالت أسماء بنت يزيد: كنتُ في النسوة المُبايعات فقلت: يا رسول الله، ابسُط يدك نبايعك. فقال لي صلى الله عليه وسلم: «إني لا أصافح النساء، لكن آخذ عليهنّ ما أخذ الله عليهنّ»». ثم نقل أنّ النّقاش ذكر حديثًا أنّ النبي صلى الله عليه وسلم مدّ يده مِن خارج بيتٍ، ومدّ نساء من الأنصار أيديهنّ من داخله، فبايعهنّ، ثم علَّق بقوله: «وما قدمتُه أثْبت».", "mawaqif": [{"taliq": 6588, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 287 - 288", "qawl": "", "nass": "اختلفت هيئات مبايعة رسول الله صلى الله عليه وسلم النساء بعد الإجماع على أنه لم تمس يده يد امرأة أجنبية، فيروى عن عائشة وغيرها أنه بايع باللسان قولا، وقال: «إنما قولي لمائة امرأة كقولي لامرأة واحدة", "qawaid": [], "tabi": ""}]}, {"id": 6589, "kinds": "بيان", "text": "قال ابنُ عطية (8/ 286 - 287): «الإتيان بالبهتان؛ قال أكثر المفسرين معناه: أن تنسب إلى زوجها ولدًا ليس هو له. واللفظ أعمُّ من هذا التخصيص؛ فإنّ الفِرية بالقول على أحد من الناس بعظيمة لَمِن هذا، وإنّ الكذب فيما ائتمنّ عليه من الحمل والحيض لَفرية بُهتان، وبعضٌ أقوى من بعض، وذلك أن بعض الناس قال: {بين أيديهن} يراد به اللسان في الكلام، والفم في القُبلة ونحوها، و (بين الأرجل) يراد به الفروج، وولد الإلحاق ونحوه».", "mawaqif": [{"taliq": 6589, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 286 - 287", "qawl": "", "nass": "الإتيان بالبهتان؛ قال أكثر المفسرين معناه: أن تنسب إلى زوجها ولدا ليس هو له. واللفظ أعم من هذا التخصيص؛ فإن الفرية بالقول على أحد من الناس بعظيمة لمن هذا، وإن الكذب فيما ائتمن عليه من الحمل والحيض لفرية بهتان، وبعض أقوى من بعض، وذلك أن بعض الناس قال: {بين أيديهن} يراد به اللسان في الكلام، والفم في القبلة ونحوها، و (بين الأرجل) يراد به الفروج، وولد الإلحاق ونحوه", "qawaid": [], "tabi": ""}]}, {"id": 6590, "kinds": "نقل", "text": "قال ابنُ عطية (8/ 287): «المعروف: الذي نُهي عن العصيان فيه. قال أنس، وابن عباس، وزيد بن أسلم: هو النّوْح، وشقّ الجيوب، ووشْم الوجوه، ووصْل الشعر، وغير ذلك من أوامر الشريعة فرضها وندْبها».\nوقال ابنُ تيمية (6/ 295): «قال: {ولا يعصينك في معروف} فقيّد المعصية، ولهذا فُسّرتْ بالنّياحة. قاله ابن عباس، ورُوي ذلك مرفوعًا. وكذلك قال زيد بن أسلم: لا يدعن ويلًا، ولا يَخْدِشن وجهًا، ولا يَنشُرن شعرًا، ولا يَشْقُقن ثوبًا. وقد قال بعضهم: هو جميع ما يأمرهم به الرسول من شرائع الإسلام وأدلته. كما قاله أبو سليمان الدمشقي. ولفظ الآية عام أنهنّ لا يَعصينه في معروف، ومعصيته لا تكون إلا في معروف؛ فإنه لا يأمر بمنكر، لكن هذا قيل: فيه دلالة على أن طاعة أولي الأمر إنما تلزم في المعروف، كما ثبت في الصحيح عن النبي صلى الله عليه وسلم أنه قال: «إنما الطاعة في المعروف». ونظير هذا قوله: {استجيبوا لله وللرسول إذا دعاكم لما يحييكم} [الأنفال: 24]، وهو لا يدعو إلا إلى ذلك».", "mawaqif": [{"taliq": 6590, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 287", "qawl": "", "nass": "المعروف: الذي نهي عن العصيان فيه. قال أنس، وابن عباس، وزيد بن أسلم: هو النوح، وشق الجيوب، ووشم الوجوه، ووصل الشعر، وغير ذلك من أوامر الشريعة فرضها وندبها", "qawaid": [], "tabi": ""}, {"taliq": 6590, "mi": 0, "aya": 12, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "6/ 295", "qawl": "", "nass": "قال: {ولا يعصينك في معروف} فقيد المعصية، ولهذا فسرت بالنياحة. قاله ابن عباس، وروي ذلك مرفوعا. وكذلك قال زيد بن أسلم: لا يدعن ويلا، ولا يخدشن وجها، ولا ينشرن شعرا، ولا يشققن ثوبا. وقد قال بعضهم: هو جميع ما يأمرهم به الرسول من شرائع الإسلام وأدلته. كما قاله أبو سليمان الدمشقي. ولفظ الآية عام أنهن لا يعصينه في معروف، ومعصيته لا تكون إلا في معروف؛ فإنه لا يأمر بمنكر، لكن هذا قيل: فيه دلالة على أن طاعة أولي الأمر إنما تلزم في المعروف، كما ثبت في الصحيح عن النبي صلى الله عليه وسلم أنه قال: «إنما الطاعة في المعروف", "qawaid": [], "tabi": ""}]}], "13": [{"id": 6591, "kinds": "غيره", "text": "قال ابنُ عطية (8/ 289): «قال ابن عباس: هم في هذه الآية كفار قريش. لأن كل كافر فعليه غضب من الله لا يرد بذلك ثبوت الغضب على اليهود … ولا سيما في المردة ككفار قريش؛ إذ أعمالهم معصية ليست بمجرد ضلال، بل فيها مناورات مقصودة».", "mawaqif": [{"taliq": 6591, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "8/ 289", "qawl": "", "nass": "قال ابن عباس: هم في هذه الآية كفار قريش. لأن كل كافر فعليه غضب من الله لا يرد بذلك ثبوت الغضب على اليهود … ولا سيما في المردة ككفار قريش؛ إذ أعمالهم معصية ليست بمجرد ضلال، بل فيها مناورات مقصودة", "qawaid": [], "tabi": ""}]}, {"id": 6592, "kinds": "خلاف،تعليق", "text": "قيل: إنّ «القوم» المشار إليهم في الآية: هم اليهود. وقيل: هم كفار مكة.\nوعَلَّق ابنُ عطية (8/ 289) على القولين بقوله: «وفي الكلام في التشبيه الذي في قوله: {كما يئس} يتبين الاحتياج إلى هذا الخلاف؛ وذلك أن اليأس من الآخرة: إما أن يكون بالتكذيب بها، وهذا هو يأس كفار مكة، وإما أن يكون باليأس عن الحظّ فيها والنعمة مع التصديق بها، وهذا هو يأس اليهود».", "mawaqif": [{"taliq": 6592, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "8/ 289", "qawl": "", "nass": "وفي الكلام في التشبيه الذي في قوله: {كما يئس} يتبين الاحتياج إلى هذا الخلاف؛ وذلك أن اليأس من الآخرة: إما أن يكون بالتكذيب بها، وهذا هو يأس كفار مكة، وإما أن يكون باليأس عن الحظ فيها والنعمة مع التصديق بها، وهذا هو يأس اليهود", "qawaid": [], "tabi": ""}]}]}, "athar": {"76559": {"num": 76559, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وإنْ فاتَكُمْ شَيْءٌ مِن أزْواجِكُمْ إلى الكُفّارِ}: الذين ليس بينكم وبينهم عهد."}, "76560": {"num": 76560, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وإنْ فاتَكُمْ شَيْءٌ مِن أزْواجِكُمْ إلى الكُفّارِ"}, "76563": {"num": 76563, "aya": 11, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مَسروق بن الأَجْدع الهَمداني -من طريق مسلم- أنه قرأها: {فَعاقَبْتُمْ}، وفسّرها: فغَنِمتم."}, "76564": {"num": 76564, "aya": 11, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النَّخْعي -من طريق مُغيرة- في قوله: {فَعاقَبْتُمْ}، قال: غَنمتم."}, "76565": {"num": 76565, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح-: أنهم كانوا أُمروا أن يَردّوا عليهم من الغنيمة. قال: وكان مجاهد يقول: {فَعاقَبْتُمْ}، يقول: فغَنِمتم."}, "76567": {"num": 76567, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- قوله: {فَآتُوا الَّذِينَ ذَهَبَتْ أزْواجُهُمْ مِثْلَ ما أنْفَقُوا}: يعني: إن لَحِقت امرأةُ رجلٍ من المهاجرين بالكفار أمر له رسولُ الله صلى الله عليه وسلم أن يُعطى مِن الغنيمة مثل ما أنفق."}, "76568": {"num": 76568, "aya": 11, "qail": "عبد الله بن عباس رضي الله عنهما قال", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس رضي الله عنهما قال: لَحِق بالمشركين من نساء المؤمنين والمهاجرين ستُّ نسوة: أُمّ الحكم بنت أبي سُفيان وكانت تحت عِياض بن شدّاد الفهريّ، وفاطمة بنت أبي أُميّة بن المُغيرة أُخت أُمّ سلمة كانت تحت عمر بن الخطاب، فلما أراد عمر أن يُهاجر أبَتْ وارتدتْ، وبَرْوَعُ بنت عُقبة كانت تحت شمّاس بن عثمان، وعزة بنت عبد العُزّى بن نَضلة وزوجها عمرو بن عبد ود، وهند بنت أبي جهل بن هشام كانت تحت هشام بن العاص بن وائل، وأُمّ كُلثوم بنت جَرول كانت تحت عمر بن الخطاب، فكلّهن رَجعنَ عن الإسلام، فأَعطى رسول الله صلى الله عليه وسلم أزواجهنّ مهور نسائهم من الغنيمة."}, "76569": {"num": 76569, "aya": 11, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مَسروق بن الأَجْدع الهَمداني -من طريق مسلم- قال: إذا ذهبت المرأةُ إلى المشركين أعْطوا زوجَها مثلَ مهرها، وإذا ذهبت إلى قوم ليس بينهما وبينهم عهد من المشركين {فَعاقَبْتُمْ} فأصبتم غنيمة {فَآتُوا الَّذِينَ ذَهَبَتْ أزْواجُهُمْ مِثْلَ ما أنْفَقُوا} يقول: آتُوا زوجها من الغنيمة مثل مهرها."}, "76570": {"num": 76570, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق خُصَيف-، مثله أو نحوه."}, "76572": {"num": 76572, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {وإنْ فاتَكُمْ شَيْءٌ مِن أزْواجِكُمْ إلى الكُفّارِ} الذين ليس بينكم وبينهم عهد {فَعاقَبْتُمْ} أصبتم مغنمًا من قريش أو غيرهم {فَآتُوا الَّذِينَ ذَهَبَتْ أزْواجُهُمْ مِثْلَ ما أنْفَقُوا} صَدُقاتهنّ عِوضًا."}, "76573": {"num": 76573, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر: {وإنْ فاتَكُمْ شَيْءٌ مِن أزْواجِكُمْ إلى الكُفّارِ فَعاقَبْتُمْ} إن امرأة من أهل مكة أتت المسلمين فعوِّضوا زوجها، وإن امرأة من المسلمين أتت المشركين فعوِّضوا زوجها، وإن امرأة من المسلمين ذهبتْ إلى مَن ليس له عهد من المشركين {فَعاقَبْتُمْ} فأصبتم غنيمة؛ فعوِّضوا زوجها مثل ما أنفق."}, "76574": {"num": 76574, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وإنْ فاتَكُمْ شَيْءٌ مِن أزْواجِكُمْ إلى الكُفّارِ فَعاقَبْتُمْ فَآتُوا الَّذِينَ ذَهَبَتْ أزْواجُهُمْ مِثْلَ ما أنْفَقُوا واتَّقُوا اللَّهَ}: كُنّ إذا فَررنَ من أصحاب النبي صلى الله عليه وسلم إلى الكفار ليس بينهم وبين نبي الله عهد، فأصاب أصحاب رسول الله صلى الله عليه وسلم غنيمة؛ أُعطي زوجها ما ساق إليها من جميع الغنيمة، ثم يَقتسمون غنيمتهم."}, "76450": {"num": 76450, "aya": 4, "qail": "مقاتل بن سليمان", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال مقاتل بن سليمان: {قَدْ كانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إبْراهِيمَ والَّذِينَ مَعَهُ} من المؤمنين؛ {إذْ قالُوا لِقَوْمِهِمْ إنّا بُرَآء مِنكُمْ ومِمّا تَعْبُدُونَ مِن دُونِ اللَّهِ} من الآلهة، {كَفَرْنا بِكُمْ} يقول: تبرّأنا منكم، {وبَدا} يعني: وظهر {بَيْنَنا وبَيْنَكُمُ العَداوَةُ والبَغْضاءُ أبَدًا حَتّى تُؤْمِنُوا بِاللَّهِ وحْدَهُ} يعني: تُصدّقوا بالله وحده."}, "76451": {"num": 76451, "aya": 4, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قول الله عز وجل: {قَدْ كانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِي إبْراهِيمَ والَّذِينَ مَعَهُ}، قال: الذين معه: الأنبياء."}, "76581": {"num": 76581, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وإنْ فاتَكُمْ شَيْءٌ مِن أزْواجِكُمْ إلى الكُفّارِ فَعاقَبْتُمْ} يقول: إلى كفار قريش، ليس بينهم وبين أصحاب النبيِّ صلى الله عليه وسلم عهد يأخذونهم به {فَعاقَبْتُمْ} وهي الغنيمة إذا غَنموا بعد ذلك، ثم نُسخ هذا الحكم وهذا العهد في براءة، فنُبذ إلى كلّ ذي عهدٍ عهده."}, "76478": {"num": 76478, "aya": 8, "qail": "عبد الله بن الزبير", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن الزّبير -من طريق عامر- قال: قَدمتْ قُتَيْلة ابنة عبد العُزّى على ابنتها أسماء بنت أبي بكر بهدايا؛ ضِباب، وأَقِطٍ، وسمْن، وهي مُشركة، فأبتْ أسماءُ أن تَقبل هدّيتها، أو تُدخلها بيتها، حتى أرسلتْ إلى عائشة: أن سَلِي عن هذا رسول الله صلى الله عليه وسلم. فسأَلتْه؛ فأنزل الله: {لا يَنْهاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقاتِلُوكُمْ فِي الدِّينِ} إلى آخر الآية. فأمَرها أن تَقبل هديّتها، وتُدخلها بيتها."}, "76479": {"num": 76479, "aya": 8, "qail": "مرة الهمداني", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "قال مُرّة الهَمداني ="}, "76481": {"num": 76481, "aya": 8, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "قال الحسن البصري: وكان هذا قبل أن يُؤمَر بقتال المشركين كافّة، كان المسلمون قبل أن يؤمر بقتالهم استشاروا النبيَّ في قرابتهم مِن المشركين أن يصِلوهم ويبرّوهم؛ فأنزل الله هذه الآية: {وتُقْسِطُوا إلَيْهِمْ}."}, "76483": {"num": 76483, "aya": 8, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق بن أبي نجيح- في قوله: {لا يَنْهاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقاتِلُوكُمْ فِي الدِّينِ}، قال: أن تَستغفروا لهم، وتَبرّوهم، وتُقسطوا إليهم، هم الذين آمنوا بمكة ولم يُهاجِروا."}, "76487": {"num": 76487, "aya": 8, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "والحسن البصري -من طريق يزيد- قالا: قال: {فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا * إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق} إلى قوله: {وأولئكم جعلنا لكم عليهم سلطانا مبينا} [النساء: 89 - 91]، وقال في الممتحنة: {لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم أن تبروهم وتقسطوا إليهم إن الله يحب المقسطين}، وقال فيها: {إنما ينهاكم الله عن الذين قاتلوكم في الدين وأخرجوكم من دياركم} إلى: {فأولئك هم الظالمون}، فنسخ هؤلاء الآيات الأربعة في شأن المشركين، فقال: {براءة من الله ورسوله إلى الذين عاهدتم من المشركين فسيحوا في الأرض أربعة أشهر واعلموا أنكم غير معجزي الله وأن الله مخزي الكافرين} [التوبة: 1 - 2]."}, "76488": {"num": 76488, "aya": 8, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "عن قتادة بن دعامة -من طريق معمر-: {لا يَنْهاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقاتِلُوكُمْ فِي الدِّينِ} نَسَختْها: {فاقْتُلُوا المُشْرِكِينَ حَيْثُ وجَدْتُمُوهُمْ} [التوبة: 5]."}, "76637": {"num": 76637, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، قال: كان عبد الله بن عمرو وزيد بن الحارث يُوادّان رجلًا مِن يهود؛ فأنزل الله: {يا أيُّها الَّذِينَ آمَنُوا لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ} الآية."}, "76639": {"num": 76639, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، {لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ}، قال: هم الكفار أصحاب القبور الذين يئسوا من الآخرة."}, "76640": {"num": 76640, "aya": 13, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال الحسن البصري: {غَضِبَ اللَّهُ عَلَيْهِمْ}، يعني: اليهود."}, "76641": {"num": 76641, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ}، قال: اليهود."}, "76644": {"num": 76644, "aya": 13, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قول الله: {يا أيُّها الَّذِينَ آمَنُوا لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ} الآية، قال: القوم الذين غضب الله عليهم يهود."}, "76646": {"num": 76646, "aya": 13, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- {قَدْ يَئِسُوا مِنَ الآخِرَةِ كَما يَئِسَ الكُفّارُ مِن أصْحابِ القُبُورِ}، قال: يعني: مَن مات من الذين كفروا، فقد يئس الأحياء من الذين كفروا أن يَرجعوا إليهم أو يبعثهم الله."}, "76648": {"num": 76648, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق الحكم- في هذه الآية: {قَدْ يَئِسُوا مِنَ الآخِرَةِ كَما يَئِسَ الكُفّارُ مِن أصْحابِ القُبُورِ}، قال: أصحاب القبور: الذين في القبور، قد يئسوا من الآخرة."}, "76649": {"num": 76649, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {قَدْ يَئِسُوا مِنَ الآخِرَةِ} قال: بكفرهم، {كَما يَئِسَ الكُفّارُ مِن أصْحابِ القُبُورِ} قال: مِن ثواب الآخرة حين تبيّن لهم أعمالهم."}, "76650": {"num": 76650, "aya": 13, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر ="}, "76653": {"num": 76653, "aya": 13, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق منصور بن زاذان- قال: {كَما يَئِسَ الكُفّارُ} الأحياء من الذين ماتوا."}, "76655": {"num": 76655, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ}، قال: اليهود قد يئسوا من الآخرة أن يُبعثوا كما يئس الكفار أن يَرجع إليهم أصحاب القبور الذين قد ماتوا."}, "76656": {"num": 76656, "aya": 13, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {كَما يَئِسَ الكُفّارُ مِن أصْحابِ القُبُورِ}، قال: إنّ الكافر إذا مات له ميت لم يرجُ لقاءَه، ولم يحتسب أجْره."}, "76657": {"num": 76657, "aya": 13, "qail": "منصور بن المعتمر", "tabaqa": "", "bab": "", "text": "عن منصور [بن المعتمر]-من طريق جرير- في قوله: {قَدْ يَئِسُوا مِنَ الآخِرَةِ} الآية، قال: قد يئسوا أن يكون لهم ثواب الآخرة، كما يئس مَن في القبور مِن الكفار من الخير، حين عاينوا العذاب والهوان."}, "76660": {"num": 76660, "aya": 13, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قول الله: {يا أيُّها الَّذِينَ آمَنُوا لا تَتَوَلَّوْا قَوْمًا غَضِبَ اللَّهُ عَلَيْهِمْ} الآية، قال: قد يئس هؤلاء الكفار مِن أن تكون لهم آخرة، كما يئس الكفار الذين ماتوا -الذين في القبور- من أن تكون لهم آخرة؛ لِما عاينوا من أمر الآخرة، فكما يئس أولئك الكفار كذلك يئس هؤلاء الكفار. قال: والقوم الذين غضب الله عليهم يهود، هم الذين يئسوا من أن تكون لهم آخرة، كما يئس الكفار قبلهم من أصحاب القبور؛ لأنهم قد علِموا كتاب الله، وأقاموا على الكفر به. وما صنعوا وقد علِموا؟!."}}, "n_athar": {"0": 9, "1": 20, "2": 1, "3": 1, "4": 9, "5": 6, "6": 2, "7": 10, "8": 16, "9": 2, "10": 63, "11": 27, "12": 53, "13": 24}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});